# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots stale refusal handoff context", type: :request do
  # "any `409 stale_generation` outside a handoff;"
  # A refusal made during a handoff must stay marked with that step after the handoff clears, or a
  # reader that looks at the ownership row later would count it as outside a handoff.
  it "keeps the handoff step a stale refusal saw even after the handoff ends, so only the later refusal counts as outside a handoff" do
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    project = create(:project, client: create(:client, company:), billable: false)
    user = create(:user)
    ownership = TimekeepingOwnership.current
    ownership.update!(generation: ownership.generation + 1)
    stale_generation = TimekeepingOwnership.current.generation - 1

    deliver_stale = lambda do |entry_id, service_token|
      entry = TimekeepingSnapshots.entry(id: entry_id, company_id: company.id, version: 1, project_id: project.id,
                                         user_id: user.id)
      body = TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: stale_generation,
                                                                         outbox_position: 1)).to_json
      post "/internal/v1/timekeeping/entry-snapshots", params: body,
                                                        headers: { "CONTENT_TYPE" => "application/json",
                                                                   "Authorization" => "Bearer #{service_token}",
                                                                   "Idempotency-Key" => SecureRandom.uuid }
    end

    with_timekeeping_service_token do |service_token|
      TimekeepingOwnership.current.update!(handoff_step: "close_admission")
      deliver_stale.call(93_001, service_token)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])

      TimekeepingOwnership.current.update!(handoff_step: nil)
      deliver_stale.call(93_002, service_token)
      expect([response.status, response.parsed_body]).to eq([409, { "reason" => "stale_generation" }])
    end

    rows = TimekeepingStaleGenerationRefusal.where(company_id: company.id).order(:created_at, :id)
    expect(rows.pluck(:handoff_step)).to eq(["close_admission", nil])
    expect(TimekeepingStaleGenerationRefusal.where(company_id: company.id, handoff_step: nil).count).to eq(1)
  end
end
